function fakeList(titles: string[], landHome = false) {
	let top = 0;
	let mode: "list" | "tip" | "home" | "kakao" = "list";
	const tapped: string[] = [];
	/** 판매관리가 아닌 화면에서 보낸 스와이프 수. 0 이어야 한다. */
	const stray = { swipes: 0, leftApp: false };
	const moves = { swipes: 0 };
	const homeXml = `<hierarchy>${["홈", "채팅", "나의 당근", "방배4동"].map((text, i) => `<node text="${text}" content-desc="" package="com.towneers.www" bounds="[${i * 200},2200][${i * 200 + 180},2300]" />`).join("")}</hierarchy>`;
	const kakaoXml = `<hierarchy><node text="채팅" content-desc="" package="com.kakao.talk" bounds="[0,0][300,100]" /></hierarchy>`;
	const maxTop = Math.max(0, titles.length - SLOTS.length);
	const listXml = () => {
		const cards = titles.slice(top, top + SLOTS.length).map((title, slot) => {
			const y = SLOTS[slot];
			return [
				node("판매중", "", 90, y, 192, y + 54),
				node("", "더보기", 935, y, 991, y + 56),
				node(title, "", 321, y + 89, 986, y + 151),
				node("방배4동 · 5일 전", "", 321, y + 157, 552, y + 208),
				node("10,000원", "", 321, y + 214, 527, y + 276),
				node("3", "", 950, y + 282, 990, y + 333),
				node("", "끌어올리기", 90, y + 372, 528, y + 473),
				node("", "홍보하기", 551, y + 372, 990, y + 473),
			].join("");
		});
		return `<hierarchy>${node("", "판매중 30", 45, 314, 299, 427)}${node("판매관리", "", 141, 157, 313, 224)}${cards.join("")}</hierarchy>`;
	};
	const adb: AdbExec = (args) => {
		const joined = args.join(" ");
		if (joined.includes("dumpsys window")) return { status: 0, stdout: "isKeyguardShowing=false", stderr: "" };
		if (joined.includes("input tap")) {
			const [, y] = args.slice(-2).map(Number);
			const slot = SLOTS.findIndex((base) => y >= base + 372 && y <= base + 473);
			if (mode === "list" && slot >= 0 && titles[top + slot]) {
				tapped.push(titles[top + slot]);
				mode = "tip";
			}
		}
		if (joined.includes("KEYCODE_BACK")) {
			// 실기 2026-11-11: 창을 닫으면 당근 홈 피드로 떨어지고, 홈에서 back 은 앞 앱(카카오톡)으로 나간다.
			if (landHome) {
				if (mode === "home") stray.leftApp = true;
				mode = mode === "home" || mode === "kakao" ? "kakao" : "home";
			} else mode = "list";
			top = 0;
		}
		if (joined.includes("karrot://my_sales")) {
			mode = "list";
			top = 0;
		}
		const moving = joined.includes("motionevent") || joined.includes("input swipe");
		if (moving) moves.swipes += 1;
		if (mode !== "list" && moving) stray.swipes += 1;
		const down = joined.match(/motionevent DOWN \d+ (\d+).*motionevent MOVE \d+ \d+ && sleep/);
		if (down) {
			const from = Number(down[1]);
			const to = Number(joined.match(/motionevent UP \d+ (\d+)/)?.[1]);
			if (to > from) top = Math.max(0, top - SLOTS.length);
			else top = Math.min(maxTop, top + SLOTS.length);
		}
		const swipe = joined.match(/input swipe \d+ (\d+) \d+ (\d+)/);
		if (swipe) top = Number(swipe[2]) < Number(swipe[1]) ? maxTop : 0;
		return { status: 0, stdout: "", stderr: "" };
	};
	const phone = Object.assign(adb, {
		droid: (args: string[]) => {
			if (args[0] !== "dump") return { status: 0, stdout: "", stderr: "" };
			const xml = mode === "tip" ? tip : mode === "home" ? homeXml : mode === "kakao" ? kakaoXml : listXml();
			return { status: 0, stdout: xml, stderr: "" };
		},
	});
	return { phone, tapped, stray, moves };
}

