1009 src/lib/macro/bump-phone.ts
/**
 * PC adb로 판매관리를 정해진 순서만 조작한다. PIN은 넣지 않는다.
 * 드라이런은 끌어올리기 창의 가격 칸만 읽고 확정·수정 완료를 누르지 않는다.
 */
import { spawnSync } from "node:child_process";
import { existsSync } from "node:fs";
import { openActionLog, type ActionLog } from "./action-log";
import type { BatchFile, BatchItem } from "./batch";
import { nextBumpAt, parseCooldownText } from "./cooldown";
import {
	cardBump,
	confirmBump,
	editPriceField,
	editPriceReady,
	forbiddenLabel,
	keyboardOpen,
	onBumpSheet,
	parseNodes,
	parseWon,
	priceField,
	type ScreenNode,
	type ScreenOp,
} from "./bump-screen";
import { droidOf } from "./droid";
import { parseSalesDump } from "./dump";
import { dumpScreen, settledDump } from "./node-dump";
import { adbExec, findPhoneSerial, PHONE_MISSING, type AdbExec } from "./phone";
import { alreadyAppliedToday, guardSnapshot } from "./rules";

const CONFIRM_BUMP = "끌어올리기";
const CONFIRM_EDIT = "수정 완료";
export const STOPPED_NOTE = "중단해서 멈췄어요";
/** 나의 당근에 판매관리 행이 없다. 앱이 등록한 내 판매 딥링크만 연다. */
export const KARROT_SALES = "karrot://my_sales";

let journal: ActionLog | null = null;
let journalSerial = "";
/** 마지막 덤프. 화면을 움직이는 명령(input·am)이 없으면 잠깐 동안 다시 쓴다. 덤프 한 번이 2초쯤 걸린다. */
let screen: { serial: string; xml: string; at: number } | null = null;
const SCREEN_REUSE_MS = 3000;

/** 화면을 바꾸는 adb 명령이 지나가면 마지막 덤프를 버린다. */
function watchMoves(exec: AdbExec): AdbExec {
	const wrapped: AdbExec = (args) => {
		const shell = args.indexOf("shell");
		const cmd = shell >= 0 ? (args[shell + 1] ?? "") : "";
		if (/^(input|am)\b/.test(cmd)) screen = null;
		return exec(args);
	};
	// `.droid` 를 들고 가야 dumpScreen 이 uiautomator 대신 `droid dump` 를 쓴다.
	const d = droidOf(exec);
	return d ? Object.assign(wrapped, { droid: d }) : wrapped;
}
let stop = false;
let stopFile: string | null = null;

/** 중단 요청(SIGTERM). 다음 단계 경계에서 멈춘다. 확정 버튼은 누르지 않는다. */
export function requestStop() {
	stop = true;
}

/**
 * 회차가 동기 코드로만 돌아 SIGTERM 핸들러가 이벤트 루프를 못 타므로, 중단 표시 파일을 단계마다 직접 본다.
 * 파일이 생기면 중단으로 친다.
 */
export function watchStopFile(path: string | null) {
	stopFile = path;
}

export function resetStop() {
	stop = false;
}

export function stopRequested(): boolean {
	if (stop) return true;
	if (stopFile !== null && existsSync(stopFile)) stop = true;
	return stop;
}

/** 끌어올리기 횟수·쿨타임을 저장소에 남기는 최소 인터페이스. bump-phone 은 저장소를 모른다. */
export type BumpBook = {
	previousBumpCount(listingId: string): number;
	recordBump(listingId: string, data: { bumpedAt: string; bumpCount: number; nextBumpAt: string | null }): void;
	recordCooldown(listingId: string, nextBumpAt: string): void;
	/** 당근에서 예약중으로 바뀐 글. 사이트가 바로 예약중으로 보이게 한다. */
	recordReserved?(listingId: string): void;
};

export type RunOptions = {
	log?: ActionLog;
	book?: BumpBook;
	/** 폰 시리얼 찾기. 기본은 droid `serial`. 테스트는 가짜를 넣는다. */
	findSerial?: () => string | null;
};

export type PhoneRun = {
	bumped: number;
	pricedOnly: number;
	skipped: number;
	note: string;
	touched: boolean;
	confirmed: boolean;
	ops: ScreenOp[];
	stopped: boolean;
	/** 실패할 때만. 사이트 메모에는 넣지 않는다. */
	logDir?: string;
};

export function keyguardLocked(blob: string): boolean | null {
	if (blob.includes("isKeyguardShowing=true")) return true;
	if (blob.includes("isKeyguardShowing=false")) return false;
	return null;
}

export function runDryWindow(base: AdbExec = adbExec, options: RunOptions = {}): PhoneRun {
	const exec = watchMoves(base);
	screen = null;
	const serial = (options.findSerial ?? findPhoneSerial)();
	if (!serial) return fail(PHONE_MISSING, false);
	const ops: ScreenOp[] = [];
	journal = options.log ?? openActionLog();
	journalSerial = serial;
	stop = false;
	wake(serial, exec);
	const locked = readLocked(serial, exec);
	if (locked) return fail("폰이 잠겨 있어요. PIN은 넣지 않아요", false);
	openSales(serial, exec);
	const opened = openReadySheet(serial, exec, ops);
	if (!opened) return fail("끌어올리기 창을 열 수 있는 글이 없어요", true, ops);
	const plan = readSheet(opened.xml, opened.title);
	backToSales(serial, exec, ops);
	if (!plan.ok) return fail(plan.message, true, ops);
	if (!noConfirm(ops)) return fail("확정 버튼을 누르지 말아야 하는데 눌렀어요", true, ops);
	return {
		bumped: 0,
		pricedOnly: 0,
		skipped: 0,
		note: `드라이런: ${opened.title} 가격 칸 ${plan.price.toLocaleString("ko-KR")}원. 확정은 누르지 않았어요`,
		touched: true,
		confirmed: false,
		ops,
		stopped: false,
	};
}

export function runApprovedOnPhone(
	batch: BatchFile,
	base: AdbExec = adbExec,
	listPrices?: ReadonlyMap<string, number>,
	options: RunOptions = {},
): PhoneRun {
	const exec = watchMoves(base);
	screen = null;
	const serial = (options.findSerial ?? findPhoneSerial)();
	if (!serial) return fail(PHONE_MISSING, false);
	const ops: ScreenOp[] = [];
	journal = options.log ?? openActionLog();
	journalSerial = serial;
	stop = false;
	wake(serial, exec);
	if (readLocked(serial, exec)) return fail("폰이 잠겨 있어요. PIN은 넣지 않아요", false);
	openSales(serial, exec);
	const tally = walkApproved(serial, exec, ops, batch, listPrices, options.book);
	const bumped = tally.bumped;
	const pricedOnly = tally.pricedOnly;
	const skipped = tally.skipped;
	const already = tally.already;
	if (tally.stop) return stopped(bumped, pricedOnly, skipped, ops, stopRequested());
	const applied = already > 0 ? `이미 오늘 가격인 ${already}건은 건너뛰었어요` : "";
	const summary = `끌어올리기 ${bumped} · 가격만 ${pricedOnly} · 건너뜀 ${skipped}`;
	return {
		bumped,
		pricedOnly,
		skipped,
		note: applied === "" ? summary : `${summary}. ${applied}`,
		touched: ops.length > 0,
		confirmed: ops.some((op) => op.kind === "tap" && (op.label === CONFIRM_BUMP || op.label === CONFIRM_EDIT)),
		ops,
		stopped: false,
	};
}

function bumpOne(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	item: BatchItem,
	dry: boolean,
	book?: BumpBook,
): "bump" | "skip" | "stop" | "gone" {
	const title = item.title;
	const price = item.proposedPrice;
	if (stopRequested()) return "stop";
	let sheet: string | null = null;
	// 탭이 움직이는 목록에 떨어져 창이 안 열릴 수 있다. 멈춘 화면을 다시 읽어 한 번 더 누른다.
	for (let attempt = 0; attempt < 2 && !sheet; attempt++) {
		const xml = attempt === 0 ? dumpXml(serial, exec) : settledXml(serial, exec);
		const node = cardBump(parseNodes(xml), title);
		// 처음 읽은 화면에 카드가 없으면 앞선 동작으로 목록이 움직인 것이다. 눌러 보지 않았으니 건너뛰지 않고 다시 찾게 돌려준다.
		if (!node) return attempt === 0 ? "gone" : "skip";
		const point = center(node);
		tap(
			serial,
			exec,
			ops,
			point.x,
			point.y,
			"카드 끌어올리기",
			`「${title}」을 ${price.toLocaleString("ko-KR")}원으로 끌어올리려고`,
		);
		if (stopRequested()) return "stop";
		sheet = waitFor(serial, exec, (text) => onBumpSheet(text) || cooldownTip(text), attempt === 0 ? 3000 : 8000);
	}
	if (!sheet || cooldownTip(sheet)) {
		nowCooldown(item.id, sheet, book);
		backToSales(serial, exec, ops);
		return "skip";
	}
	// 목록이 다시 그려지는 사이 다른 카드를 눌렀을 수 있다. 연 창의 제목이 다르면 아무것도 바꾸지 않고 닫는다.
	if (!showsTitle(sheet, title)) {
		noteSkip(title, "연 끌어올리기 창의 제목이 달라서");
		backToSales(serial, exec, ops);
		return "skip";
	}
	const ready = ensurePrice(serial, exec, ops, sheet, price, dry);
	if (ready === "stop") return "stop";
	if (dry) {
		backToSales(serial, exec, ops);
		return ready === "skip" ? "skip" : "bump";
	}
	if (ready === "skip") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	// 가격을 하나도 확정하지 않은 채로 멈춘다. 그만두기를 먼저 누른다.
	if (stopRequested()) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	if (
		!confirmMatchingPrice(
			serial,
			exec,
			ops,
			price,
			CONFIRM_BUMP,
			`「${title}」 ${price.toLocaleString("ko-KR")}원 확정`,
		)
	) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	recordBumped(item.id, book);
	backToSales(serial, exec, ops);
	return "bump";
}

function priceOne(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	item: BatchItem,
	dry: boolean,
): "price" | "skip" | "stop" | "gone" {
	const title = item.title;
	const price = item.proposedPrice;
	if (stopRequested()) return "stop";
	let menu: string | null = null;
	// 탭이 움직이는 목록에 떨어져 메뉴가 안 열릴 수 있다. 멈춘 화면을 다시 읽어 한 번 더 누른다.
	for (let attempt = 0; attempt < 2 && !menu; attempt++) {
		const xml = attempt === 0 ? dumpXml(serial, exec) : settledXml(serial, exec);
		const more = moreFor(parseNodes(xml), title);
		if (!more) return attempt === 0 ? "gone" : "skip";
		const at = center(more);
		tap(serial, exec, ops, at.x, at.y, "더보기", `「${title}」 가격만 ${price.toLocaleString("ko-KR")}원으로 맞추려고`);
		menu = waitFor(serial, exec, (text) => text.includes("게시글 수정"), 4000);
	}
	if (!menu) {
		backToSales(serial, exec, ops);
		return "skip";
	}
	const edit = parseNodes(menu).find((node) => node.text === "게시글 수정");
	if (!edit || forbiddenLabel(edit.text, edit.desc)) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	const editAt = center(edit);
	tap(serial, exec, ops, editAt.x, editAt.y, "게시글 수정", `「${title}」 수정 창을 열려고`);
	const form = scrollToEditPrice(serial, exec, ops);
	if (!form) {
		noteSkip(title, "수정 창에서 가격 칸을 못 찾아서");
		backToSales(serial, exec, ops);
		return "skip";
	}
	const ready = ensurePrice(serial, exec, ops, form, price, dry, true);
	if (ready === "stop") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	if (dry) {
		backToSales(serial, exec, ops);
		return ready === "skip" ? "skip" : "price";
	}
	if (ready === "skip") {
		backToSales(serial, exec, ops);
		return "skip";
	}
	if (stopRequested()) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	if (
		!confirmMatchingPrice(
			serial,
			exec,
			ops,
			price,
			CONFIRM_EDIT,
			`「${title}」 ${price.toLocaleString("ko-KR")}원 저장`,
		)
	) {
		backToSales(serial, exec, ops);
		return "stop";
	}
	backToSales(serial, exec, ops);
	return "price";
}

/** 성공한 끌어올리기의 횟수·쿨타임을 남긴다. 횟수는 이전+1, 다음 시각은 추정표. */
function recordBumped(listingId: string, book?: BumpBook) {
	if (!book) return;
	const bumpedAt = new Date().toISOString();
	const bumpCount = book.previousBumpCount(listingId) + 1;
	book.recordBump(listingId, { bumpedAt, bumpCount, nextBumpAt: nextBumpAt(bumpedAt, bumpCount) });
}

/** 폰에 뜬 남은 시간 문구를 읽어 다음 끌어올림 시각을 남긴다. 문구를 못 읽으면 아무것도 하지 않는다. */
function nowCooldown(listingId: string, xml: string | null, book?: BumpBook) {
	if (!book || !xml) return;
	const text = cooldownText(xml);
	if (!text) return;
	const next = parseCooldownText(text, new Date());
	if (next) book.recordCooldown(listingId, next);
}

/** 화면에서 쿨타임 문구를 꺼낸다. 판매팁·끌어올릴 수 있어요 문구가 있는 노드 중 가장 긴 글. */
export function cooldownText(xml: string): string | null {
	const texts = parseNodes(xml)
		.flatMap((node) => [node.text, node.desc])
		.filter((text) => text !== "" && cooldownTip(text))
		.sort((left, right) => right.length - left.length);
	return texts[0] ?? null;
}

function scrollToEditPrice(serial: string, exec: AdbExec, ops: ScreenOp[]): string | null {
	let prev = "";
	for (let page = 0; page < 8; page++) {
		if (stopRequested()) return null;
		const xml = dumpXml(serial, exec);
		if (editPriceReady(parseNodes(xml), CONFIRM_EDIT)) return xml;
		const key = parseNodes(xml)
			.map((node) => node.text)
			.filter(Boolean)
			.slice(0, 8)
			.join("|");
		if (page > 0 && key !== "" && key === prev) return null;
		prev = key;
		swipeStep(serial, exec, ops, "가격 칸이 아직 안 보여서");
	}
	return null;
}

function imeShown(serial: string, exec: AdbExec): boolean {
	const blob = exec(["-s", serial, "shell", "dumpsys", "input_method"]).stdout;
	return blob.includes("mInputShown=true") || /mImeWindowVis=[1-9]/.test(blob) || keyboardOpen(blob);
}

function confirmMatchingPrice(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	want: number,
	label: string,
	reason: string,
): boolean {
	if (imeShown(serial, exec) || keyboardOpen(dumpXml(serial, exec))) {
		act(
			serial,
			{ cmd: "key", action: "키보드를 닫음", reason: "확정 버튼이 가려져서" },
			() => {
				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
				sleep(400);
			},
			() => "키보드만 닫으려고 뒤로 감",
		);
	}
	if (imeShown(serial, exec)) return false;
	let xml = dumpXml(serial, exec);
	if (keyboardOpen(xml)) return false;
	const shown = parseNodes(xml);
	const field = editPriceField(shown) ?? priceField(shown);
	if (!field || parseWon(field.text) !== want) {
		noteSkip(label, `가격 칸이 ${field ? field.text : "없음"}이라 ${want.toLocaleString("ko-KR")}원 확정을 안 누름`);
		return false;
	}
	let nodes = parseNodes(xml);
	let confirm =
		label === CONFIRM_BUMP ? confirmBump(nodes) : nodes.find((node) => node.text === label || node.desc === label);
	for (let page = 0; !confirm && label === CONFIRM_EDIT && page < 4; page++) {
		swipeStep(serial, exec, ops, "수정 완료가 아직 안 보여서");
		xml = dumpXml(serial, exec);
		const again = editPriceField(parseNodes(xml));
		if (again && parseWon(again.text) !== want) return false;
		nodes = parseNodes(xml);
		confirm = nodes.find((node) => node.text === label || node.desc === label);
	}
	if (!confirm || forbiddenLabel(confirm.text, confirm.desc)) return false;
	// 중단 요청은 확정 직전에서만 본다. 칸에 쓴 값은 그만두기로 버린다.
	if (stopRequested()) return false;
	const at = center(confirm);
	tap(serial, exec, ops, at.x, at.y, label, reason);
	const after = dumpXml(serial, exec);
	const savedNodes = parseNodes(after);
	const saved = editPriceField(savedNodes) ?? priceField(savedNodes);
	if (saved && parseWon(saved.text) !== want) {
		noteSkip(label, `확정 뒤 칸이 ${saved.text}이라 저장하지 않고 닫음`);
		exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
		sleep(400);
		return false;
	}
	return true;
}

function ensurePrice(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	xml: string,
	want: number,
	dry: boolean,
	currency = false,
): "ok" | "skip" | "stop" {
	const nodes = parseNodes(xml);
	const field = currency ? editPriceField(nodes) : (priceField(nodes) ?? editPriceField(nodes));
	if (!field) return "stop";
	if (parseWon(field.text) === want) return "ok";
	if (dry) return "ok";
	// 지우기·입력은 확정 전이라 버릴 수 있다. 중단이면 아예 쓰지 않는다.
	if (stopRequested()) return "stop";
	let changed = false;
	act(
		serial,
		{
			cmd: "input",
			action: `가격 칸을 ${want.toLocaleString("ko-KR")}원으로 바꿈`,
			reason: `칸이 ${field.text}이라서`,
			target: String(want),
		},
		() => {
			const at = center(field);
			ops.push({ kind: "tap", x: at.x, y: at.y, label: "가격" });
			exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
			sleep(300);
			for (let i = 0; i < 8; i++) key(serial, exec, "KEYCODE_DEL");
			sleep(200);
			for (const digit of String(want)) {
				if (stopRequested()) break;
				key(serial, exec, `KEYCODE_${digit}`);
			}
			sleep(400);
			const againNodes = parseNodes(dumpXml(serial, exec));
			const again = currency ? editPriceField(againNodes) : (priceField(againNodes) ?? editPriceField(againNodes));
			changed = Boolean(again && parseWon(again.text) === want);
		},
		() => (changed ? `${want.toLocaleString("ko-KR")}원으로 바뀜` : "가격이 안 바뀌어서 확정하지 않음"),
	);
	return changed ? "ok" : "stop";
}

function openReadySheet(serial: string, exec: AdbExec, ops: ScreenOp[]): { xml: string; title: string } | null {
	const seen = new Set<string>();
	for (let page = 0; page < 12; page++) {
		if (stopRequested()) return null;
		let xml = dumpXml(serial, exec);
		if (cooldownTip(xml)) {
			backToSales(serial, exec, ops);
			xml = dumpXml(serial, exec);
		}
		const nodes = parseNodes(xml);
		const bumps = nodes.filter((node) => node.desc === "끌어올리기" && !forbiddenLabel(node.text, node.desc));
		let tapped = false;
		for (const bump of bumps) {
			const title = titleAbove(nodes, bump);
			if (!title || seen.has(title)) continue;
			seen.add(title);
			const point = center(bump);
			tap(serial, exec, ops, point.x, point.y, "카드 끌어올리기", `「${title}」 끌어올리기 창의 가격만 읽으려고`);
			const next = waitFor(serial, exec, (text) => onBumpSheet(text) || cooldownTip(text), 5000);
			if (next && onBumpSheet(next)) return { xml: next, title };
			backToSales(serial, exec, ops);
			tapped = true;
			break;
		}
		if (!tapped) swipeUp(serial, exec, ops, "이 화면의 끌어올리기는 대기 중이라 다음 글을 보러");
	}
	return null;
}

function titleAbove(nodes: ScreenNode[], bump: ScreenNode): string {
	const title = nodes
		.filter(
			(node) =>
				node.text &&
				node.y <= bump.y &&
				node.y > bump.y - 420 &&
				!node.text.includes("·") &&
				!/^[\d,]+원?$/.test(node.text) &&
				node.text !== "판매중" &&
				node.text !== "판매관리" &&
				node.text !== "원",
		)
		.sort((a, b) => b.y - a.y)[0];
	return title?.text ?? "";
}

/** 화면에 그 글의 제목이 있는가. 긴 제목은 칸에서 잘려도 노드 text 는 온전하다. */
function showsTitle(xml: string, title: string): boolean {
	return parseNodes(xml).some((node) => node.text.includes(title) || node.desc.includes(title));
}

function cooldownTip(xml: string): boolean {
	return xml.includes("판매팁") || xml.includes("끌어올릴 수 있어요");
}

function moreFor(nodes: ScreenNode[], title: string): ScreenNode | null {
	const titleNode = nodes.find((node) => node.text === title);
	if (!titleNode) return null;
	return (
		nodes.find(
			(node) =>
				node.desc === "더보기" &&
				!forbiddenLabel(node.text, node.desc) &&
				node.y >= titleNode.y - 160 &&
				node.y < titleNode.y + 420,
		) ?? null
	);
}

function readSheet(xml: string, title: string): { ok: true; price: number } | { ok: false; message: string } {
	if (!onBumpSheet(xml)) return { ok: false, message: "끌어올리기 창이 아니에요" };
	const field = priceField(parseNodes(xml));
	if (!field) return { ok: false, message: "가격 칸이 없어요" };
	if (title && !xml.includes(title)) return { ok: false, message: "연 글의 제목이 덤프에 없어요" };
	return { ok: true, price: parseWon(field.text) };
}

function openSales(serial: string, exec: AdbExec) {
	const xml = dumpXml(serial, exec);
	if (onSales(xml)) return;
	let opened = false;
	act(
		serial,
		{ cmd: "open", action: "판매관리를 염", reason: "판매중 목록이 아니라서" },
		() => {
			exec(["-s", serial, "shell", "am", "start", "-a", "android.intent.action.VIEW", "-d", KARROT_SALES]);
			sleep(800);
		},
		() => {
			opened = onSales(dumpXml(serial, exec));
			return opened ? "판매관리가 열림" : `판매관리가 안 열림 (지금 화면: ${focusOf(serial, exec)})`;
		},
		() => opened,
	);
}

function onSales(xml: string): boolean {
	return xml.includes("판매관리") && (xml.includes("끌어올리기") || xml.includes("판매중 "));
}

function backToSales(serial: string, exec: AdbExec, ops: ScreenOp[]) {
	for (let i = 0; i < 4; i++) {
		const xml = dumpXml(serial, exec);
		if (xml.includes("판매관리") && !xml.includes("그만두기")) return;
		const discard = parseNodes(xml).find((node) => node.text === "그만두기");
		if (discard) {
			const at = center(discard);
			act(
				serial,
				{ cmd: "tap", action: "그만두기를 누름", reason: "바꾼 가격이 저장되면 안 되어서" },
				() => {
					exec(["-s", serial, "shell", "input", "tap", String(at.x), String(at.y)]);
					sleep(400);
				},
				() => "수정을 저장하지 않고 닫음",
			);
			continue;
		}
		act(
			serial,
			{ cmd: "back", action: "뒤로 감", reason: "판매중 목록으로 돌아가려고" },
			() => {
				ops.push({ kind: "back" });
				exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_BACK"]);
				sleep(400);
			},
			() => (dumpXml(serial, exec).includes("판매관리") ? "판매관리로 돌아옴" : "아직 다른 화면"),
		);
	}
}

function waitFor(serial: string, exec: AdbExec, pred: (xml: string) => boolean, ms: number): string | null {
	const log = journal;
	const startMs = log?.now() ?? 0;
	const start = Date.now();
	let found: string | null = null;
	while (Date.now() - start < ms) {
		if (stopRequested()) break;
		const xml = dumpXml(serial, exec, true);
		if (pred(xml)) {
			found = xml;
			break;
		}
		sleep(350);
	}
	const endMs = log?.now() ?? 0;
	log?.next(
		{
			cmd: "wait",
			action: "화면을 기다림",
			reason: `${ms}ms 안에 기대한 화면이 되기를 기다려서`,
			result: found ? "기대한 화면이 됨" : stopRequested() ? "중단 요청으로 멈춤" : "기다려도 안 바뀜",
			ok: found !== null,
		},
		{ startMs, endMs },
	);
	return found;
}

function dumpXml(serial: string, exec: AdbExec, fresh = false): string {
	if (!fresh && screen && screen.serial === serial && Date.now() - screen.at < SCREEN_REUSE_MS) return screen.xml;
	const log = serial === journalSerial ? journal : null;
	const startMs = log?.now() ?? 0;
	const xml = dumpScreen(serial, exec);
	const endMs = log?.now() ?? 0;
	log?.next(
		{
			cmd: "dump",
			action: "화면 덤프",
			reason: "지금 화면을 읽으려고",
			target: "",
			result: `${xml.length}바이트`,
			ok: xml.length > 0,
		},
		{ startMs, endMs },
	);
	screen = xml.length > 0 ? { serial, xml, at: Date.now() } : null;
	return xml;
}

/**
 * 목록이 멈춘 화면을 읽는다. 스와이프 뒤 목록은 플링으로 더 미끄러지므로, 덤프 좌표로 누르면 빈 곳이나 움직이는 목록을 눌러
 * 메뉴가 안 열린다(2026-11-06 19:00 회차에서 로맨틱무브 이하 6건이 이렇게 건너뛰어졌다). `settledDump`로 연속 두 덤프가 같을 때까지 기다린다.
 */
function settledXml(serial: string, exec: AdbExec): string {
	return settledDump(() => dumpXml(serial, exec, true), sleep);
}

function wake(serial: string, exec: AdbExec) {
	exec(["-s", serial, "shell", "input", "keyevent", "KEYCODE_WAKEUP"]);
}

function readLocked(serial: string, exec: AdbExec): boolean {
	const blob = exec(["-s", serial, "shell", "dumpsys", "window"]).stdout;
	return keyguardLocked(blob) !== false;
}

function tap(serial: string, exec: AdbExec, ops: ScreenOp[], x: number, y: number, label: string, reason = label) {
	if (forbiddenLabel(label, label)) {
		noteSkip(label, "누르지 않는 버튼이라서");
		return;
	}
	act(
		serial,
		{ cmd: "tap", action: `${label}을 누름`, reason, target: `${x},${y}` },
		() => {
			ops.push({ kind: "tap", x, y, label });
			exec(["-s", serial, "shell", "input", "tap", String(x), String(y)]);
			sleep(500);
		},
		() => "탭을 보냈어요",
	);
}

function key(serial: string, exec: AdbExec, name: string) {
	exec(["-s", serial, "shell", "input", "keyevent", name]);
}

/** 목록 끝까지 민다. 노출이 최근인 글이 위, 오래된 글이 아래다. */
function scrollToEdge(serial: string, exec: AdbExec, ops: ScreenOp[], edge: "top" | "bottom") {
	let prev = "";
	let stuck = 0;
	for (let page = 0; page < 24; page++) {
		if (stopRequested()) return;
		const parsed = parseSalesDump(page === 0 ? dumpXml(serial, exec) : settledXml(serial, exec));
		const cards = parsed.ok ? parsed.cards : [];
		const head = (edge === "top" ? cards[0]?.title : cards[cards.length - 1]?.title) ?? "";
		if (page > 0 && head !== "" && head === prev) {
			stuck += 1;
			if (stuck >= 2) return;
		} else {
			stuck = 0;
		}
		prev = head;
		swipeList(
			serial,
			exec,
			ops,
			edge === "top" ? "판매중 목록을 맨 위에서 읽으려고" : "판매중 목록을 맨 아래에서 읽으려고",
			edge === "top" ? "up" : "bottom",
		);
	}
}

type Tally = { bumped: number; pricedOnly: number; skipped: number; already: number; stop: boolean };

/**
 * 승인 글을 폰에서 처리한다. 당근 목록은 마지막 노출이 최근인 글이 위, 오래된 글이 아래다. 맨 아래로 내려간 뒤
 * 위로 한 번만 걸으며 만나는 대로 처리한다(끌어올리기와 가격만 수정을 함께). 노출이 가장 오래된 글이 먼저 끝나고,
 * 중간에 실패하거나 멈춰도 급한 글이 먼저 처리돼 있다. 끌어올리기 대상은 노출이 오래된 글이라 대부분 아래쪽에 있어서
 * 맨 위로 되돌아가는 두 번째 걷기가 필요 없다.
 */
function walkApproved(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	batch: BatchFile,
	listPrices?: ReadonlyMap<string, number>,
	book?: BumpBook,
): Tally {
	const tally: Tally = { bumped: 0, pricedOnly: 0, skipped: 0, already: 0, stop: false };
	const pending = new Map(batch.items.map((item) => [item.title, item]));
	for (const item of batch.items) {
		const listed = listPrices?.get(item.id);
		if (listed === undefined || !alreadyAppliedToday(listed, item.proposedPrice, item.snapshot.price)) continue;
		tally.skipped += 1;
		tally.already += 1;
		noteSkip(item.title, "목록 가격이 승인된 오늘 가격과 같아서");
		pending.delete(item.title);
	}
	if (pending.size === 0) return tally;
	walkUp(serial, exec, ops, pending, tally, book);
	return tally;
}

/** 맨 아래에서 위로 걷는 한 판을 되풀이하는 상한. 끌올이 하루 6개라 한 판에 하나씩만 끝나는 최악에도 모자라지 않는다. */
const MAX_WALK_PASSES = 8;

/**
 * 맨 아래에서 위로 걸으며 남은 글을 처리한다. 끌올하거나 창을 닫고 돌아오면 목록이 맨 위로 되돌아가
 * 위로만 걷는 한 판은 아래·가운데 글에 닿지 못한 채 끝난다(2026-11-07 가격만 12건·끌올 1건 놓침).
 * 한 판에서 하나라도 처리했는데 남은 글이 있으면 맨 아래부터 다시 걷는다. 진전이 없으면 멈춘다.
 */
function walkUp(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	pending: Map<string, BatchItem>,
	tally: Tally,
	book?: BumpBook,
) {
	for (let pass = 0; pass < MAX_WALK_PASSES && pending.size > 0; pass++) {
		const before = pending.size;
		walkPass(serial, exec, ops, pending, tally, book);
		if (tally.stop || pending.size === before) break;
	}
	for (const title of pending.keys()) {
		tally.skipped += 1;
		noteSkip(title, "판매중 목록에서 제목을 못 찾음");
	}
}

function walkPass(
	serial: string,
	exec: AdbExec,
	ops: ScreenOp[],
	pending: Map<string, BatchItem>,
	tally: Tally,
	book?: BumpBook,
) {
	scrollToEdge(serial, exec, ops, "bottom");
	let prev = "";
	let stuck = 0;
	let page = 0;
	for (let turn = 0; turn < 60 && page < 24 && pending.size > 0; turn++) {
		if (stopRequested()) {
			tally.stop = true;
			return;
		}
		let reread = false;
		const xml = settledXml(serial, exec);
		const nodes = parseNodes(xml);
		const parsed = parseSalesDump(xml);
		if (parsed.ok) {
			// 아래에서 위로 걸을 때는 화면 아래 카드부터. 오래 노출 안 된 글이 먼저다.
			for (const card of [...parsed.cards].reverse()) {
				const item = pending.get(card.title);
				if (!item) continue;
				// 예약중 글은 거래 약속이 잡혀 있다. 저장소가 아직 모르더라도 폰 화면이 예약중이면 건드리지 않는다.
				if (card.reserved) {
					tally.skipped += 1;
					noteSkip(item.title, "당근에서 예약중이라서");
					book?.recordReserved?.(item.id);
					pending.delete(item.title);
					continue;
				}
				if (alreadyAppliedToday(card.price, item.proposedPrice, item.snapshot.price)) {
					tally.skipped += 1;
					tally.already += 1;
					noteSkip(item.title, "카드 가격이 승인된 오늘 가격과 같아서");
					pending.delete(item.title);
					continue;
				}
				const verdict = guardSnapshot(item.snapshot, card);
				if (!verdict.run) {
					tally.skipped += 1;
					noteSkip(item.title, "가격이 승인 때와 달라서");
					pending.delete(item.title);
					continue;
				}
				const visible = item.action === "bump" ? cardBump(nodes, item.title) : moreFor(nodes, item.title);
				if (!visible) continue;
				const done =
					item.action === "bump"
						? bumpOne(serial, exec, ops, item, false, book)
						: priceOne(serial, exec, ops, item, false);
				// 카드가 화면에서 사라졌다. 목록이 움직였으니 글은 남겨 두고, 다시 읽어 찾는다.
				if (done === "gone") {
					reread = true;
					break;
				}
				pending.delete(item.title);
				if (done === "stop") {
					backToSales(serial, exec, ops);
					tally.stop = true;
					return;
				}
				if (done === "bump") tally.bumped += 1;
				else if (done === "price") tally.pricedOnly += 1;
				else tally.skipped += 1;
				if (stopRequested()) {
					tally.stop = true;
					return;
				}
				// 끌어올린 글은 목록 맨 위로 옮겨 가 화면 배치가 바뀐다. 이 덤프의 나머지 카드는 믿지 않고 다시 읽는다.
				if (done === "bump") {
					reread = true;
					break;
				}
			}
		}
		if (pending.size === 0) break;
		if (reread) continue;
		const key = parsed.ok ? parsed.cards.map((card) => card.title).join("|") : "";
		if (page > 0 && key !== "" && key === prev) {
			stuck += 1;
			if (stuck >= 2) break;
		} else {
			stuck = 0;
		}
		prev = key;
		swipeList(serial, exec, ops, "남은 승인 글을 보러", "back");
		page += 1;
	}
}

const LIST_MOVES = {
	down: { from: 1550, to: 700, drag: true, action: "목록을 내림", result: "다음 글을 봤어요" },
	back: { from: 700, to: 1550, drag: true, action: "목록을 되돌림", result: "앞 글을 봤어요" },
	up: { from: 750, to: 1650, drag: false, action: "목록을 맨 위로 올림", result: "앞 글을 보러 올렸어요" },
	bottom: { from: 1650, to: 750, drag: false, action: "목록을 맨 아래로 내림", result: "뒷 글을 보러 내렸어요" },
} as const;

/** 한 화면씩 옮길 때(down·back)는 손을 멈춘 뒤 떼서 목록이 더 미끄러지지 않게 한다. 끝으로 보낼 때(up·bottom)는 플링이 빨라 그대로 둔다. */
function swipeList(serial: string, exec: AdbExec, ops: ScreenOp[], reason: string, dir: keyof typeof LIST_MOVES) {
	const move = LIST_MOVES[dir];
	act(
		serial,
		{ cmd: "swipe", action: move.action, reason },
		() => {
			ops.push({ kind: "tap", x: 420, y: 1100, label: "목록 이동" });
			if (move.drag) drag(serial, exec, 420, move.from, move.to);
			else {
				exec(["-s", serial, "shell", "input", "swipe", "420", String(move.from), "420", String(move.to), "200"]);
				sleep(250);
			}
		},
		() => move.result,
	);
}

function swipeStep(serial: string, exec: AdbExec, ops: ScreenOp[], reason: string) {
	act(
		serial,
		{ cmd: "swipe", action: "목록을 조금 올림", reason },
		() => {
			ops.push({ kind: "tap", x: 400, y: 860, label: "목록 이동" });
			drag(serial, exec, 400, 1300, 700);
		},
		() => "다음 글을 겹쳐 봤어요",
	);
}

function swipeUp(serial: string, exec: AdbExec, ops: ScreenOp[], reason: string) {
	act(
		serial,
		{ cmd: "swipe", action: "목록을 올림", reason },
		() => {
			ops.push({ kind: "tap", x: 400, y: 900, label: "목록 이동" });
			drag(serial, exec, 400, 1100, 450);
		},
		() => "다음 글을 보러 올렸어요",
	);
}

/**
 * 손을 멈춘 뒤 떼는 끌기. `input swipe`는 짧을수록 빨라 플링이 붙고, 수정 창에서 가격 칸을 건너뛰어 바닥까지 갔다.
 * 끝점에서 잠깐 머문 뒤 UP 해서 속도가 0으로 끝나게 한다. adb 왕복은 한 번이다.
 */
function drag(serial: string, exec: AdbExec, x: number, from: number, to: number) {
	const mid = Math.round((from + to) / 2);
	const steps = [
		`input motionevent DOWN ${x} ${from}`,
		`input motionevent MOVE ${x} ${mid}`,
		`input motionevent MOVE ${x} ${to}`,
		"sleep 0.25",
		`input motionevent UP ${x} ${to}`,
	].join(" && ");
	exec(["-s", serial, "shell", steps]);
	sleep(250);
}

function noteSkip(target: string, reason: string) {
	journal?.next({ cmd: "note", action: "건너뜀", reason, result: "화면을 움직이지 않음", target });
}

/** 한 단계의 시작·끝을 회차 시각으로 남긴다. 확정 전 중단은 이 단계 사이에서만 일어난다. */
function act(
	serial: string,
	record: { cmd: string; action: string; reason: string; target?: string; ok?: boolean },
	run: () => void,
	result: () => string,
	ok?: () => boolean,
) {
	const log = serial === journalSerial ? journal : null;
	const startMs = log?.now() ?? 0;
	run();
	const outcome = result();
	const endMs = log?.now() ?? 0;
	log?.next({ ...record, result: outcome, ...(ok ? { ok: ok() } : {}) }, { startMs, endMs });
}

/** 앞에 떠 있는 창(패키지/액티비티). 판매관리가 아닐 때 무엇이 가렸는지 로그에 남긴다. */
export function focusOf(serial: string, exec: AdbExec): string {
	const blob = exec(["-s", serial, "shell", "dumpsys", "window"]).stdout;
	return blob.match(/mCurrentFocus=Window\{\S+ \S+ ([^}\s]+)\}/)?.[1] ?? "모름";
}

function center(node: { x: number; y: number; w: number; h: number }) {
	return {
		x: Math.floor(node.x + node.w / 2),
		y: Math.floor(node.y + node.h / 2),
	};
}

function noConfirm(ops: ScreenOp[]): boolean {
	return ops.every((op) => op.kind !== "tap" || (op.label !== CONFIRM_BUMP && op.label !== CONFIRM_EDIT));
}

function fail(note: string, touched: boolean, ops: ScreenOp[] = []): PhoneRun {
	return {
		bumped: 0,
		pricedOnly: 0,
		skipped: 0,
		note,
		touched,
		confirmed: false,
		ops,
		stopped: false,
		logDir: journal?.dir,
	};
}

function stopped(bumped: number, pricedOnly: number, skipped: number, ops: ScreenOp[], byUser: boolean): PhoneRun {
	return {
		bumped,
		pricedOnly,
		skipped,
		note: byUser ? STOPPED_NOTE : "가격 칸이 승인값과 달라 확정하지 않았어요",
		touched: true,
		confirmed: false,
		ops,
		stopped: byUser,
		logDir: journal?.dir,
	};
}

function sleep(ms: number) {
	spawnSync("sleep", [(ms / 1000).toFixed(3)]);
}

import { describe, expect, test } from "bun:test";
