/** 아래에서 위로 모을 때, 보이는 창의 위→아래를 이미 모은 순서에 끼워 넣는다. */
export function mergeSalesOrder<T extends { title: string; thumb?: string | null }>(existing: T[], window: T[]): T[] {
	const byTitle = new Map(existing.map((card) => [card.title, card]));
	for (const card of window) {
		const prior = byTitle.get(card.title);
		byTitle.set(card.title, prior ? { ...prior, ...card, thumb: card.thumb ?? prior.thumb ?? null } : card);
	}
	const order = existing.map((card) => card.title);
	const index = new Map(order.map((title, at) => [title, at]));
	const fresh = window.filter((card) => !index.has(card.title));
	if (fresh.length === window.length && fresh.length > 0) {
		return [
			...fresh.map((card) => byTitle.get(card.title)).filter((card): card is T => card !== undefined),
			...order.map((title) => byTitle.get(title)).filter((card): card is T => card !== undefined),
		];
	}
	for (let i = 0; i < window.length; i++) {
		const title = window[i]?.title;
		if (!title || index.has(title)) continue;
		let insertAt = order.length;
		let placed = false;
		for (let j = i + 1; j < window.length; j++) {
			const next = index.get(window[j]?.title ?? "");
			if (next !== undefined) {
				insertAt = next;
				placed = true;
				break;
			}
		}
		if (!placed) {
			for (let j = i - 1; j >= 0; j--) {
				const prev = index.get(window[j]?.title ?? "");
				if (prev !== undefined) {
					insertAt = prev + 1;
					break;
				}
			}
		}
		order.splice(insertAt, 0, title);
		index.clear();
		order.forEach((name, at) => index.set(name, at));
	}
	return order.map((title) => byTitle.get(title)).filter((card): card is T => card !== undefined);
}

function uniqueByTitle(cards: DumpCard[]): DumpCard[] {
	const seen = new Set<string>();
	const out: DumpCard[] = [];
	for (const card of cards) {
		if (seen.has(card.title)) continue;
		seen.add(card.title);
		out.push(card);
	}
	return out;
}

